#!/usr/bin/env python3
"""Original additional English/Russian practice tasks for lessons 1–51."""
import json,pathlib
ROOT=pathlib.Path(__file__).resolve().parents[1]
course=json.loads((ROOT/'Sources/SQLCore/Resources/curriculum.json').read_text())
lessons={l['id']:l for m in course['modules'] for t in m['topics'] for l in t['lessons']}
items=[]
def add(n,title,prompt,rt,rp,sql,validation=None,kind='query'):
 lid=f'l{n:03}';lesson=lessons[lid]
 used=[int(e['id'].split('-e')[1]) for e in lesson['exercises'] if not e.get('isExtension')]+[int(e['id'].split('-e')[1]) for e in items if e['lessonID']==lid]
 eid=lid+'-e'+str(max(used)+1)
 items.append(dict(lessonID=lid,id=eid,title=title,prompt=prompt,difficulty='Beginner' if n<=12 else 'Intermediate',kind=kind,starterSQL='-- Write your PostgreSQL query here\n',solutionSQL=sql,fixtureIDs=lesson['exercises'][0]['fixtureIDs'],ordered=True,columnNames=True,hints=['Identify the output columns and the intended result grain.',lesson['sections'][2]['body'],lesson['sections'][7]['body']],explanation=lesson['sections'][0]['body']+' '+lesson['sections'][2]['body'],**({'validationSQL':validation} if validation else {}),ru=dict(title=rt,prompt=rp)))
add(1,'Read employee records','Return id, name, and department from employees ordered by id.','Записи сотрудников','Верните id, name и department из employees в порядке id.','SELECT id,name,department FROM employees ORDER BY id;')
add(1,'Read hotel dates','Return id, room, check_in, and check_out from bookings ordered by id.','Даты гостиничных бронирований','Верните id, room, check_in и check_out из bookings в порядке id.','SELECT id,room,check_in,check_out FROM bookings ORDER BY id;')
add(2,'Read event ownership','Return id and customer_id from events ordered by id. A NULL relationship must remain NULL.','Владельцы событий','Верните id и customer_id из events в порядке id. Сохраните NULL в связях.','SELECT id,customer_id FROM events ORDER BY id;')
add(2,'Connect the inventory key','Return product_id, warehouse, and quantity from inventory ordered by product_id.','Ключ складской записи','Верните product_id, warehouse и quantity из inventory в порядке product_id.','SELECT product_id,warehouse,quantity FROM inventory ORDER BY product_id;')
add(3,'Proposed discount prices','Return id and discounted_price equal to price multiplied by 0.9 for each product, ordered by id.','Расчёт скидки','Верните id и discounted_price = price * 0.9 для каждого товара в порядке id.','SELECT id,price*0.9 AS discounted_price FROM products ORDER BY id;')
add(3,'Increase account balances in a report','Without changing accounts, return id and projected_balance equal to balance+25, ordered by id.','Прогноз остатков без изменения данных','Не меняя accounts, верните id и projected_balance = balance + 25 в порядке id.','SELECT id,balance+25 AS projected_balance FROM accounts ORDER BY id;')
add(4,'Employee directory aliases','Return employees.id as employee_id and employees.name as employee_name, ordered by id.','Псевдонимы справочника сотрудников','Верните employees.id как employee_id и employees.name как employee_name в порядке id.','SELECT id AS employee_id,name AS employee_name FROM employees ORDER BY id;')
add(4,'Booking label columns','Return room as room_number and guest as guest_name from bookings ordered by id.','Подписи бронирования','Верните room как room_number и guest как guest_name из bookings в порядке id.','SELECT room AS room_number,guest AS guest_name FROM bookings ORDER BY id;')
add(5,'Distinct warehouses','Return each warehouse once from inventory ordered alphabetically.','Уникальные склады','Верните каждый warehouse из inventory один раз в алфавитном порядке.','SELECT DISTINCT warehouse FROM inventory ORDER BY warehouse;')
add(5,'Distinct booking date pairs','Return distinct check_in and check_out pairs from bookings ordered by check_in then check_out.','Уникальные пары дат','Верните различные пары check_in и check_out из bookings в порядке check_in, затем check_out.','SELECT DISTINCT check_in,check_out FROM bookings ORDER BY check_in,check_out;')
add(6,'Top three salaries','Return id,name,salary for the three highest-paid employees, salary descending and id ascending on ties.','Три наибольшие зарплаты','Верните id, name и salary трёх сотрудников с наибольшей зарплатой; salary по убыванию, id по возрастанию при равенстве.','SELECT id,name,salary FROM employees ORDER BY salary DESC,id LIMIT 3;')
add(6,'Recent order page','Return id and ordered_on for orders ordered newest date first then highest id; skip the first row and take four.','Страница последних заказов','Верните id и ordered_on в порядке от новой даты к старой, затем id по убыванию. Пропустите одну строку и возьмите четыре.','SELECT id,ordered_on FROM orders ORDER BY ordered_on DESC,id DESC LIMIT 4 OFFSET 1;')
add(7,'Large account balances','Return id,owner,balance from accounts where balance>=750, ordered by id.','Крупные остатки счетов','Верните id, owner и balance из accounts с balance >= 750 в порядке id.','SELECT id,owner,balance FROM accounts WHERE balance>=750 ORDER BY id;')
add(7,'Affordable hotel nights','Return id,guest,room for bookings with nightly_rate<=100, ordered by id.','Невысокая стоимость ночи','Верните id, guest и room бронирований с nightly_rate <= 100 в порядке id.','SELECT id,guest,room FROM bookings WHERE nightly_rate<=100 ORDER BY id;')
add(8,'VIP customers outside Paris','Return id,name for VIP customers whose city is known and is not Paris, ordered by id.','VIP за пределами Парижа','Верните id и name VIP-клиентов с известным city, не равным Paris, в порядке id.','SELECT id,name FROM customers WHERE vip AND city IS NOT NULL AND city<>\'Paris\' ORDER BY id;')
add(8,'Urgent product selection','Return id,name for products that either have stock=0 or have both category Tech and price<100, ordered by id.','Срочный отбор товаров','Верните id и name товаров: stock равен 0 либо одновременно category = Tech и price < 100. Сортируйте по id.','SELECT id,name FROM products WHERE stock=0 OR (category=\'Tech\' AND price<100) ORDER BY id;')
add(9,'Open order statuses','Return id,status for orders in pending or cancelled status ordered by id.','Незавершённые статусы','Верните id и status заказов со статусом pending или cancelled в порядке id.','SELECT id,status FROM orders WHERE status IN(\'pending\',\'cancelled\') ORDER BY id;')
add(9,'Salary interval','Return id,salary for employees with salary between 70000 and 90000 inclusive, ordered by salary then id.','Интервал зарплат','Верните id и salary сотрудников с salary от 70000 до 90000 включительно. Сортируйте по salary, затем id.','SELECT id,salary FROM employees WHERE salary BETWEEN 70000 AND 90000 ORDER BY salary,id;')
add(10,'Unknown customer orders','Return id,total for orders with NULL customer_id ordered by id.','Заказы неизвестных клиентов','Верните id и total заказов с NULL в customer_id в порядке id.','SELECT id,total FROM orders WHERE customer_id IS NULL ORDER BY id;')
add(10,'Null-safe city equality','Return id and is_london from customers using a NULL-safe equality comparison with London, ordered by id. NULL cities must produce false.','Безопасное равенство города','Верните id и is_london клиентов с NULL-безопасным сравнением с London в порядке id. Для NULL результат false.','SELECT id,city IS NOT DISTINCT FROM \'London\' AS is_london FROM customers ORDER BY id;')
add(11,'Names ending in a','Return id,name for customer names ending in a, ignoring case, ordered by id.','Имена на a','Верните id и name клиентов, имя которых заканчивается на a без учёта регистра. Сортируйте по id.','SELECT id,name FROM customers WHERE name ILIKE \'%a\' ORDER BY id;')
add(11,'Product names with a second-letter a','Return id,name for products whose second character is a, ordered by id.','Буква a на второй позиции','Верните id и name товаров, в названии которых второй символ равен a. Сортируйте по id.','SELECT id,name FROM products WHERE name LIKE \'_a%\' ORDER BY id;')
add(12,'Names not beginning A through D','Return id,name for customers whose name does not start with A,B,C,D, case-insensitively, ordered by id.','Имена вне начального диапазона','Верните id и name клиентов, имя которых не начинается с A, B, C или D без учёта регистра. Сортируйте по id.','SELECT id,name FROM customers WHERE name !~* \'^[a-d]\' ORDER BY id;')
add(12,'Remove email domains','Return id and local_part using a regular-expression replacement that removes @ and everything after it from known emails, ordered by id.','Удаление почтового домена','Для известных email верните id и local_part, удалив регулярной заменой @ и всё после него. Сортируйте по id.','SELECT id,regexp_replace(email,\'@.*$\',\'\') AS local_part FROM customers WHERE email IS NOT NULL ORDER BY id;')
add(13,'Product price bands','Return id,price_band: budget for price<10, regular for price<100, premium otherwise; order by id.','Ценовые группы товаров','Верните id и price_band: budget при price < 10, regular при price < 100, иначе premium. Сортируйте по id.','SELECT id,CASE WHEN price<10 THEN \'budget\' WHEN price<100 THEN \'regular\' ELSE \'premium\' END AS price_band FROM products ORDER BY id;')
add(13,'Shipment progress labels','Return id,delivery_state: sent when shipped_on is known, cancelled when status=cancelled, otherwise waiting; order by id.','Состояние доставки','Верните id и delivery_state: sent при известной shipped_on, cancelled при status = cancelled, иначе waiting. Сортируйте по id.','SELECT id,CASE WHEN shipped_on IS NOT NULL THEN \'sent\' WHEN status=\'cancelled\' THEN \'cancelled\' ELSE \'waiting\' END AS delivery_state FROM orders ORDER BY id;')
add(14,'Fallback shipment date','Return id and effective_day using shipped_on when known, otherwise ordered_on; order by id.','Резервная дата заказа','Верните id и effective_day: shipped_on, если известна, иначе ordered_on. Сортируйте по id.','SELECT id,COALESCE(shipped_on,ordered_on) AS effective_day FROM orders ORDER BY id;')
add(14,'Hide zero stock values','Return id and nonzero_stock equal to stock except zero becomes NULL, ordered by id.','Замена нулевого остатка на NULL','Верните id и nonzero_stock: stock, но ноль замените на NULL. Сортируйте по id.','SELECT id,NULLIF(stock,0) AS nonzero_stock FROM products ORDER BY id;')
add(15,'Exact percentage of price','Return id and discounted_price equal to price*0.875 cast to numeric(10,2), ordered by id.','Точная цена после скидки','Верните id и discounted_price = price * 0.875, приведённую к numeric(10,2). Сортируйте по id.','SELECT id,(price*0.875)::numeric(10,2) AS discounted_price FROM products ORDER BY id;')
add(15,'Parsed fixed values','Return parsed_integer from text 0042 cast to integer and parsed_date from text 2024-08-15 cast to date.','Преобразование текстовых значений','Верните parsed_integer из текста 0042 типа integer и parsed_date из текста 2024-08-15 типа date.','SELECT \'0042\'::integer AS parsed_integer,CAST(\'2024-08-15\' AS date) AS parsed_date;')
add(16,'Shipment coverage counts','Return order_count and shipped_count from COUNT(*) and COUNT(shipped_on) over orders.','Полнота дат отгрузки','Верните order_count и shipped_count через COUNT(*) и COUNT(shipped_on) по orders.','SELECT count(*) AS order_count,count(shipped_on) AS shipped_count FROM orders;')
add(16,'Distinct customer references','Return known_customers as COUNT(DISTINCT customer_id) from orders.','Уникальные ссылки на клиентов','Верните known_customers как COUNT(DISTINCT customer_id) из orders.','SELECT count(DISTINCT customer_id) AS known_customers FROM orders;')
add(17,'Hotel gross charges','Return total_charge as the sum of booking nights times nightly_rate.','Общая стоимость проживания','Верните total_charge — сумму числа ночей, умноженного на nightly_rate, по всем бронированиям.','SELECT sum((check_out-check_in)*nightly_rate) AS total_charge FROM bookings;')
add(17,'Salary endpoints','Return lowest_salary and highest_salary from employees.','Границы зарплат','Верните lowest_salary и highest_salary из employees.','SELECT min(salary) AS lowest_salary,max(salary) AS highest_salary FROM employees;')
add(18,'Stock by availability','Return empty_products and stocked_products using aggregate FILTER for stock=0 and stock>0.','Наличие товаров','Верните empty_products и stocked_products через FILTER агрегатов для stock = 0 и stock > 0.','SELECT count(*) FILTER(WHERE stock=0) AS empty_products,count(*) FILTER(WHERE stock>0) AS stocked_products FROM products;')
add(18,'Shipment revenue split','Return shipped_revenue and unshipped_revenue as sums of paid order totals split by shipped_on known/NULL.','Выручка по наличию отгрузки','Верните shipped_revenue и unshipped_revenue — суммы total оплаченных заказов для известной shipped_on и NULL соответственно.','SELECT sum(total) FILTER(WHERE shipped_on IS NOT NULL) AS shipped_revenue,sum(total) FILTER(WHERE shipped_on IS NULL) AS unshipped_revenue FROM orders WHERE status=\'paid\';')
add(19,'Warehouse unit totals','Return warehouse and units as sum(quantity) from inventory grouped by warehouse, ordered by warehouse.','Количество единиц по складам','Верните warehouse и units = sum(quantity) из inventory по складам в порядке warehouse.','SELECT warehouse,sum(quantity) AS units FROM inventory GROUP BY warehouse ORDER BY warehouse;')
add(19,'Orders by calendar day','Return ordered_on and order_count for each order date, ordered by ordered_on.','Заказы по календарным дням','Верните ordered_on и order_count для каждой даты заказа в порядке ordered_on.','SELECT ordered_on,count(*) AS order_count FROM orders GROUP BY ordered_on ORDER BY ordered_on;')
add(20,'Warehouses above fifty units','Return warehouse and units for warehouses with sum(quantity)>50, ordered by warehouse.','Склады с большим запасом','Верните warehouse и units складов с sum(quantity) > 50 в порядке warehouse.','SELECT warehouse,sum(quantity) AS units FROM inventory GROUP BY warehouse HAVING sum(quantity)>50 ORDER BY warehouse;')
add(20,'Repeated salary values','Return salary and employee_count for salaries shared by more than one employee, ordered by salary.','Повторяющиеся зарплаты','Верните salary и employee_count зарплат, которые есть у нескольких сотрудников. Сортируйте по salary.','SELECT salary,count(*) AS employee_count FROM employees GROUP BY salary HAVING count(*)>1 ORDER BY salary;')
add(21,'Status rollup count','Return status,order_count,is_total for ROLLUP(status), details alphabetically then grand total.','Итоги количества по статусам','Верните status, order_count и is_total для ROLLUP(status): детали по алфавиту, затем общий итог.','SELECT status,count(*) AS order_count,grouping(status) AS is_total FROM orders GROUP BY ROLLUP(status) ORDER BY is_total,status;')
add(21,'Warehouse and grand total','Use GROUPING SETS to return warehouse,units,is_total for warehouse sums and the grand total, details first alphabetically.','Складские и общие итоги','Через GROUPING SETS верните warehouse, units и is_total для сумм складов и общего итога. Сначала детали по алфавиту.','SELECT warehouse,sum(quantity) AS units,grouping(warehouse) AS is_total FROM inventory GROUP BY GROUPING SETS((warehouse),()) ORDER BY is_total,warehouse;')
add(22,'Order contacts','Return order_id,customer_name,email for orders with a known customer using INNER JOIN, ordered by order_id.','Контакты по заказам','Через INNER JOIN верните order_id, customer_name и email заказов с известным клиентом. Сортируйте по order_id.','SELECT o.id AS order_id,c.name AS customer_name,c.email FROM orders o JOIN customers c ON c.id=o.customer_id ORDER BY o.id;')
add(22,'Sold product prices','Return order_id,product_id,name,unit_price,current_price for every order line joined to products, ordered by order_id then product_id.','Цена покупки и текущая цена','Соедините позиции с products и верните order_id, product_id, name, unit_price и current_price. Сортируйте по order_id, затем product_id.','SELECT i.order_id,i.product_id,p.name,i.unit_price,p.price AS current_price FROM order_items i JOIN products p ON p.id=i.product_id ORDER BY i.order_id,i.product_id;')
add(23,'Customer event counts','Return customer_id and event_count for every customer, including zero, ordered by customer_id.','Количество событий клиента','Верните customer_id и event_count каждого клиента, включая ноль. Сортируйте по customer_id.','SELECT c.id AS customer_id,count(e.id) AS event_count FROM customers c LEFT JOIN events e ON e.customer_id=c.id GROUP BY c.id ORDER BY c.id;')
add(23,'Products with no order lines','Use LEFT JOIN to return id,name of products with no order_items, ordered by id.','Товары без позиций заказов','Через LEFT JOIN верните id и name товаров без order_items. Сортируйте по id.','SELECT p.id,p.name FROM products p LEFT JOIN order_items i ON i.product_id=p.id WHERE i.product_id IS NULL ORDER BY p.id;')
add(24,'All event and customer links','FULL JOIN customers to events on customer_id and return customer_id,event_id, including unmatched rows, ordered by customer_id NULLS LAST then event_id NULLS LAST.','Все связи событий и клиентов','Соедините customers FULL JOIN events по customer_id. Верните customer_id и event_id, включая строки без пары. Сортируйте по customer_id NULLS LAST, затем event_id NULLS LAST.','SELECT c.id AS customer_id,e.id AS event_id FROM customers c FULL JOIN events e ON e.customer_id=c.id ORDER BY customer_id NULLS LAST,event_id NULLS LAST;')
add(24,'Small product pairing grid','CROSS JOIN products to accounts. Return product_id,account_id for products id<=2 and accounts id<=2, ordered by both IDs.','Небольшая сетка пар','Выполните CROSS JOIN products и accounts. Верните product_id и account_id для id товаров <= 2 и id счетов <= 2. Сортируйте по обоим id.','SELECT p.id AS product_id,a.id AS account_id FROM products p CROSS JOIN accounts a WHERE p.id<=2 AND a.id<=2 ORDER BY p.id,a.id;')
add(25,'Employees sharing a manager','Return first_id,second_id for employee pairs with the same non-NULL manager_id, first_id<second_id, ordered by both IDs.','Сотрудники одного руководителя','Верните first_id и second_id пар сотрудников с одинаковым известным manager_id. first_id < second_id. Сортируйте по обоим id.','SELECT a.id AS first_id,b.id AS second_id FROM employees a JOIN employees b ON a.manager_id=b.manager_id AND a.id<b.id ORDER BY a.id,b.id;')
add(25,'Direct report salary difference','Return id,name,manager_name,salary_difference as employee salary minus manager salary for employees with a manager, ordered by id.','Разница зарплат подчинённого и руководителя','Для сотрудников с руководителем верните id, name, manager_name и salary_difference — зарплату сотрудника минус зарплата руководителя. Сортируйте по id.','SELECT e.id,e.name,m.name AS manager_name,e.salary-m.salary AS salary_difference FROM employees e JOIN employees m ON m.id=e.manager_id ORDER BY e.id;')
add(26,'Paid product quantities','Return product_id,name,sold_units from paid order lines joined through orders to products, ordered by product_id.','Оплаченные количества товаров','Верните product_id, name и sold_units оплаченных позиций, соединив orders, order_items и products. Сортируйте по product_id.','SELECT p.id AS product_id,p.name,sum(i.quantity) AS sold_units FROM products p JOIN order_items i ON i.product_id=p.id JOIN orders o ON o.id=i.order_id WHERE o.status=\'paid\' GROUP BY p.id ORDER BY p.id;')
add(26,'Customer category purchases','Return customer_id,category,line_count for paid order lines of known customers, ordered by customer_id then category.','Покупки категорий клиентами','Для оплаченных позиций известных клиентов верните customer_id, category и line_count. Сортируйте по customer_id, затем category.','SELECT c.id AS customer_id,p.category,count(*) AS line_count FROM customers c JOIN orders o ON o.customer_id=c.id JOIN order_items i ON i.order_id=o.id JOIN products p ON p.id=i.product_id WHERE o.status=\'paid\' GROUP BY c.id,p.category ORDER BY c.id,p.category;')
add(27,'Customers without pending orders','Return id,name of customers with no pending order, including customers with no orders, ordered by id.','Клиенты без ожидающих заказов','Верните id и name клиентов без заказов pending, включая клиентов вообще без заказов. Сортируйте по id.','SELECT c.id,c.name FROM customers c WHERE NOT EXISTS(SELECT 1 FROM orders o WHERE o.customer_id=c.id AND o.status=\'pending\') ORDER BY c.id;')
add(27,'Employees who manage others','Return id,name of employees with at least one direct report, ordered by id.','Сотрудники с подчинёнными','Верните id и name сотрудников, у которых есть хотя бы один прямой подчинённый. Сортируйте по id.','SELECT e.id,e.name FROM employees e WHERE EXISTS(SELECT 1 FROM employees child WHERE child.manager_id=e.id) ORDER BY e.id;')
add(28,'Cheapest stock','Return id,name,stock for every product tied for the minimum product price, ordered by id.','Запас самых дешёвых товаров','Верните id, name и stock всех товаров с минимальной ценой каталога. Сортируйте по id.','SELECT id,name,stock FROM products WHERE price=(SELECT min(price) FROM products) ORDER BY id;')
add(28,'Salary share of all employees','Return id,salary_share as salary divided by total employee salary rounded to four decimals, ordered by id.','Доля зарплаты в общей сумме','Верните id и salary_share — зарплату, делённую на общую сумму зарплат с округлением до четырёх знаков. Сортируйте по id.','SELECT id,round(salary/(SELECT sum(salary) FROM employees),4) AS salary_share FROM employees ORDER BY id;')
add(29,'Above customer average orders','Return id,customer_id,total for orders above the average total for their own known customer, ordered by id.','Заказы выше среднего клиента','Верните id, customer_id и total заказов выше среднего total своего известного клиента. Сортируйте по id.','SELECT o.id,o.customer_id,o.total FROM orders o WHERE o.customer_id IS NOT NULL AND o.total>(SELECT avg(x.total) FROM orders x WHERE x.customer_id=o.customer_id) ORDER BY o.id;')
add(29,'Cheapest within category','Return id,name,category for every product tied for its category minimum price, ordered by id.','Самые дешёвые в категории','Верните id, name и category всех товаров с минимальной ценой своей категории. Сохраните равные цены и сортируйте по id.','SELECT p.id,p.name,p.category FROM products p WHERE p.price=(SELECT min(x.price) FROM products x WHERE x.category=p.category) ORDER BY p.id;')
add(30,'First order per customer','Using LATERAL, return customer_id,first_order_id,ordered_on for every customer, including NULL when absent. Earliest date then smallest id wins; output by customer_id.','Первый заказ каждого клиента','Через LATERAL верните customer_id, first_order_id и ordered_on всех клиентов, с NULL при отсутствии. Выбирайте раннюю дату и меньший id; итог по customer_id.','SELECT c.id AS customer_id,o.id AS first_order_id,o.ordered_on FROM customers c LEFT JOIN LATERAL(SELECT id,ordered_on FROM orders WHERE customer_id=c.id ORDER BY ordered_on,id LIMIT 1)o ON true ORDER BY c.id;')
add(30,'Department salary leaders','Use a derived set of departments with LATERAL to return department,id,name of the highest-paid employee, smallest id on ties; output by department.','Лидер зарплаты отдела','Через производный набор отделов и LATERAL верните department, id и name самого высокооплачиваемого сотрудника отдела; при равенстве меньший id. Итог по department.','SELECT d.department,e.id,e.name FROM (SELECT DISTINCT department FROM employees)d CROSS JOIN LATERAL(SELECT id,name FROM employees WHERE department=d.department ORDER BY salary DESC,id LIMIT 1)e ORDER BY d.department;')
add(31,'Low category stock stage','Use a CTE to sum stock by category; return category,units only where units<100, ordered by category.','Этап малых запасов категории','Через CTE просуммируйте stock по категориям. Верните category и units только при units < 100 в порядке category.','WITH category_stock AS(SELECT category,sum(stock) AS units FROM products GROUP BY category) SELECT category,units FROM category_stock WHERE units<100 ORDER BY category;')
add(31,'Paid order dates stage','Use a CTE of paid orders to return ordered_on and paid_count by date, ordered by ordered_on.','Этап дат оплаченных заказов','Через CTE оплаченных заказов верните ordered_on и paid_count по датам в порядке ordered_on.','WITH paid AS(SELECT ordered_on FROM orders WHERE status=\'paid\') SELECT ordered_on,count(*) AS paid_count FROM paid GROUP BY ordered_on ORDER BY ordered_on;')
add(32,'Names across entity types','Return each distinct name from customers and employees under column person, ordered by person.','Имена разных сущностей','Верните различные name из customers и employees под именем person в порядке person.','SELECT name AS person FROM customers UNION SELECT name FROM employees ORDER BY person;')
add(32,'Separate paid and pending amounts','Using UNION ALL return status,total from paid and pending orders, preserving duplicates and sorting by status then total.','Суммы оплаченных и ожидающих заказов','Через UNION ALL верните status и total оплаченных и ожидающих заказов. Сохраните повторы; сортируйте по status, затем total.','SELECT status,total FROM orders WHERE status=\'paid\' UNION ALL SELECT status,total FROM orders WHERE status=\'pending\' ORDER BY status,total;')
add(33,'VIP customers who paid','Using INTERSECT return id of VIP customers who have paid orders, ordered by id.','VIP с оплаченными заказами','Через INTERSECT верните id VIP-клиентов с оплаченными заказами в порядке id.','SELECT id FROM customers WHERE vip INTERSECT SELECT customer_id FROM orders WHERE status=\'paid\' ORDER BY id;')
add(33,'Unpurchased product IDs','Using EXCEPT return product id as id for products with no order_items, ordered by id.','Некупленные идентификаторы товаров','Через EXCEPT верните id товаров без order_items в порядке id.','SELECT id FROM products EXCEPT SELECT product_id FROM order_items ORDER BY id;')
add(34,'Add a fixed event','Insert event 50 for customer 1 at 2024-08-01 12:00, kind visit, payload device tablet and pages 2. Return id,customer_id,kind.','Добавление события','Вставьте событие 50 клиента 1 на 2024-08-01 12:00, kind visit, payload с device tablet и pages 2. Верните id, customer_id и kind.','INSERT INTO events VALUES(50,1,\'2024-08-01 12:00\',\'visit\',\'{"device":"tablet","pages":2}\') RETURNING id,customer_id,kind;','SELECT id,customer_id,occurred_at,kind,payload FROM events ORDER BY id;','modify')
add(34,'Snapshot stocked product names','Create stocked_names(id integer PRIMARY KEY,name text NOT NULL) and INSERT SELECT all product IDs/names with stock>0.','Снимок названий товаров в наличии','Создайте stocked_names(id integer PRIMARY KEY,name text NOT NULL). Через INSERT SELECT добавьте id и name всех товаров со stock > 0.','CREATE TABLE stocked_names(id integer PRIMARY KEY,name text NOT NULL); INSERT INTO stocked_names SELECT id,name FROM products WHERE stock>0;','SELECT id,name FROM stocked_names ORDER BY id;','design')
add(35,'Close selected pending orders','Set status=cancelled for pending orders with total<100, changing no other order fields.','Закрытие небольших ожидающих заказов','Установите status = cancelled у заказов pending с total < 100. Остальные поля не меняйте.','UPDATE orders SET status=\'cancelled\' WHERE status=\'pending\' AND total<100;','SELECT * FROM orders ORDER BY id;','modify')
add(35,'Consolidate North inventory','Change inventory.warehouse from North to Central for all matching rows and preserve quantities/dates.','Объединение северного склада','Измените inventory.warehouse с North на Central у всех подходящих строк, сохранив количества и даты.','UPDATE inventory SET warehouse=\'Central\' WHERE warehouse=\'North\';','SELECT * FROM inventory ORDER BY product_id;','modify')
add(36,'Delete old visits','Delete visit events before 2024-07-02, leaving purchases and later events unchanged.','Удаление старых посещений','Удалите события visit до 2024-07-02. Покупки и более поздние события сохраните.','DELETE FROM events WHERE kind=\'visit\' AND occurred_at<\'2024-07-02\';','SELECT * FROM events ORDER BY id;','modify')
add(36,'Remove cancelled order lines','Delete order_items belonging to cancelled orders while preserving the orders themselves.','Удаление позиций отменённых заказов','Удалите order_items отменённых заказов, сохранив сами orders.','DELETE FROM order_items i USING orders o WHERE o.id=i.order_id AND o.status=\'cancelled\';','SELECT * FROM order_items ORDER BY order_id,product_id;','modify')
add(37,'Warehouse reassignment upsert','Upsert inventory for product 3 with warehouse Central,quantity 20,date 2024-08-10; on conflict replace warehouse and date but preserve current quantity.','Upsert с сохранением количества','Вставьте inventory товара 3: Central, 20, 2024-08-10. При конфликте замените склад и дату, сохранив текущее quantity.','INSERT INTO inventory VALUES(3,\'Central\',20,\'2024-08-10\') ON CONFLICT(product_id) DO UPDATE SET warehouse=EXCLUDED.warehouse,updated_on=EXCLUDED.updated_on;','SELECT * FROM inventory ORDER BY product_id;','modify')
add(37,'Insert an optional new customer safely','Insert customer id 70,name Nika,city Oslo,joined_on 2024-08-10,vip false and NULL email; on id conflict do nothing.','Безопасная вставка необязательного клиента','Добавьте клиента 70: Nika, Oslo, joined_on 2024-08-10, vip false, email NULL. При конфликте id ничего не меняйте.','INSERT INTO customers(id,name,city,joined_on,vip) VALUES(70,\'Nika\',\'Oslo\',\'2024-08-10\',false) ON CONFLICT(id) DO NOTHING;','SELECT * FROM customers ORDER BY id;','modify')
add(38,'Commit paired account adjustments','In one explicit transaction subtract 30 from account 2 and add 30 to account 3, then commit.','Связанные корректировки счетов','В одной явной транзакции снимите 30 со счёта 2 и добавьте 30 на счёт 3, затем зафиксируйте.','BEGIN; UPDATE accounts SET balance=balance-30 WHERE id=2; UPDATE accounts SET balance=balance+30 WHERE id=3; COMMIT;','SELECT * FROM accounts ORDER BY id;','modify')
add(38,'Rollback stock but keep price','In a transaction increase product 1 price by 1, create savepoint stock_draft, increase its stock by 100, rollback to that savepoint, and commit.','Откат запаса с сохранением цены','В транзакции повысьте price товара 1 на 1, создайте SAVEPOINT stock_draft, прибавьте к stock 100, откатитесь к точке и выполните COMMIT.','BEGIN; UPDATE products SET price=price+1 WHERE id=1; SAVEPOINT stock_draft; UPDATE products SET stock=stock+100 WHERE id=1; ROLLBACK TO SAVEPOINT stock_draft; COMMIT;','SELECT id,price,stock FROM products ORDER BY id;','modify')
add(39,'Capture stock updates','Use an UPDATE CTE to increase stock by 3 for Tech products; return id,stock ordered by id.','Получение изменённых запасов','Через UPDATE CTE увеличьте stock товаров Tech на 3. Верните id и stock в порядке id.','WITH changed AS(UPDATE products SET stock=stock+3 WHERE category=\'Tech\' RETURNING id,stock) SELECT id,stock FROM changed ORDER BY id;','SELECT id,stock FROM products ORDER BY id;','modify')
add(39,'Move cancelled lines to an archive','Create cancelled_lines(order_id integer,product_id integer,quantity integer). Use DELETE RETURNING in a CTE to move cancelled order lines into it.','Перенос отменённых позиций в архив','Создайте cancelled_lines(order_id integer,product_id integer,quantity integer). Через DELETE RETURNING в CTE перенесите туда позиции отменённых заказов.','CREATE TABLE cancelled_lines(order_id integer,product_id integer,quantity integer); WITH moved AS(DELETE FROM order_items i USING orders o WHERE o.id=i.order_id AND o.status=\'cancelled\' RETURNING i.order_id,i.product_id,i.quantity) INSERT INTO cancelled_lines SELECT * FROM moved;','SELECT order_id,product_id,quantity FROM cancelled_lines ORDER BY order_id,product_id;','modify')
add(40,'Choose integer widths','Return ordinary_type as pg_typeof(42)::text and wide_type as pg_typeof(10000000000)::text.','Выбор размера целого числа','Верните ordinary_type как pg_typeof(42)::text и wide_type как pg_typeof(10000000000)::text.','SELECT pg_typeof(42)::text AS ordinary_type,pg_typeof(10000000000)::text AS wide_type;')
add(40,'Known Boolean states','Return id,is_vip,is_not_vip from customers using vip and NOT vip, ordered by id.','Известные логические состояния','Верните id, is_vip и is_not_vip из customers через vip и NOT vip в порядке id.','SELECT id,vip AS is_vip,NOT vip AS is_not_vip FROM customers ORDER BY id;')
add(41,'Enum priority order','Create enum ticket_priority(low,normal,high), table tickets(id integer PRIMARY KEY,priority ticket_priority NOT NULL); insert (1,high),(2,low),(3,normal).','Порядок приоритетов enum','Создайте enum ticket_priority(low,normal,high) и tickets(id integer PRIMARY KEY,priority ticket_priority NOT NULL). Вставьте (1,high), (2,low), (3,normal).','CREATE TYPE ticket_priority AS ENUM(\'low\',\'normal\',\'high\'); CREATE TABLE tickets(id integer PRIMARY KEY,priority ticket_priority NOT NULL); INSERT INTO tickets VALUES(1,\'high\'),(2,\'low\'),(3,\'normal\');','SELECT id,priority FROM tickets ORDER BY priority,id;','design')
add(41,'UUID equality ignores text case','Return same_identifier comparing uppercase and lowercase UUID literals 123E4567-E89B-12D3-A456-426614174000 and 123e4567-e89b-12d3-a456-426614174000 as uuid.','Регистр текстовой записи UUID','Верните same_identifier, сравнив UUID-литералы 123E4567-E89B-12D3-A456-426614174000 и 123e4567-e89b-12d3-a456-426614174000 после приведения к uuid.','SELECT \'123E4567-E89B-12D3-A456-426614174000\'::uuid=\'123e4567-e89b-12d3-a456-426614174000\'::uuid AS same_identifier;')
add(42,'Trim and uppercase a fixed label','Return normalized as uppercase text after trimming both ends of the literal two spaces then office then two spaces.','Обрезка пробелов и верхний регистр','Верните normalized — текст Office в верхнем регистре после удаления двух пробелов с каждой стороны литерала office.','SELECT upper(trim(\'  office  \')) AS normalized;')
add(42,'First three product letters','Return id,prefix as the first three characters of each product name, ordered by id.','Первые три буквы товара','Верните id и prefix — первые три символа name каждого товара в порядке id.','SELECT id,left(name,3) AS prefix FROM products ORDER BY id;')
add(43,'Three-day booking follow-ups','Return id,follow_up_day equal to check_out+3 days for bookings, ordered by id.','Напоминание после выезда','Верните id и follow_up_day — дату через три дня после check_out каждого бронирования в порядке id.','SELECT id,check_out+3 AS follow_up_day FROM bookings ORDER BY id;')
add(43,'Client tenure at a fixed date','Return id,days_joined as 2024-08-01 minus joined_on for customers, ordered by id.','Стаж клиента на заданную дату','Верните id и days_joined — разность DATE 2024-08-01 и joined_on клиентов в порядке id.','SELECT id,DATE \'2024-08-01\'-joined_on AS days_joined FROM customers ORDER BY id;')
add(44,'Winter New York wall time','Return new_york_time as timestamp without time zone for instant 2024-01-15 12:00:00+00 displayed in America/New_York.','Зимнее время Нью-Йорка','Верните new_york_time типа timestamp without time zone для момента 2024-01-15 12:00:00+00 в America/New_York.','SELECT TIMESTAMPTZ \'2024-01-15 12:00:00+00\' AT TIME ZONE \'America/New_York\' AS new_york_time;')
add(44,'Summer New York wall time','Return new_york_time as timestamp without time zone for instant 2024-07-15 12:00:00+00 displayed in America/New_York.','Летнее время Нью-Йорка','Верните new_york_time типа timestamp without time zone для момента 2024-07-15 12:00:00+00 в America/New_York.','SELECT TIMESTAMPTZ \'2024-07-15 12:00:00+00\' AT TIME ZONE \'America/New_York\' AS new_york_time;')
add(45,'Weekly event counts','Return week_start as date and event_count by date_trunc week of occurred_at, ordered by week_start.','События по неделям','Верните week_start типа date и event_count по date_trunc week от occurred_at в порядке week_start.','SELECT date_trunc(\'week\',occurred_at)::date AS week_start,count(*) AS event_count FROM events GROUP BY week_start ORDER BY week_start;')
add(45,'Interval delivery deadline','Return id,deadline as ordered_on plus interval 48 hours for pending orders, ordered by id.','Срок доставки через интервал','Верните id и deadline — ordered_on плюс INTERVAL 48 hours ожидающих заказов в порядке id.','SELECT id,ordered_on+INTERVAL \'48 hours\' AS deadline FROM orders WHERE status=\'pending\' ORDER BY id;')
add(46,'Any work or light tag','Return id,name for products whose tags overlap ARRAY[work,light], ordered by id.','Хотя бы одна нужная метка','Верните id и name товаров, tags которых пересекается с ARRAY[work,light]. Сортируйте по id.','SELECT id,name FROM products WHERE tags && ARRAY[\'work\',\'light\'] ORDER BY id;')
add(46,'USB tag positions','Return id,usb_position using array_position(tags,usb) for every product, NULL when absent, ordered by id.','Позиция метки USB','Верните id и usb_position через array_position(tags,usb) каждого товара, NULL при отсутствии. Сортируйте по id.','SELECT id,array_position(tags,\'usb\') AS usb_position FROM products ORDER BY id;')
add(47,'Event page counts','Return id,pages as integer extracted from payload for every event, NULL when missing, ordered by id.','Число страниц событий','Верните id и pages типа integer, извлечённое из payload каждого события, с NULL при отсутствии. Сортируйте по id.','SELECT id,(payload->>\'pages\')::integer AS pages FROM events ORDER BY id;')
add(47,'Missing product ratings','Return id,name of products where attributes->>rating is SQL NULL, ordered by id.','Товары без рейтинга','Верните id и name товаров, у которых attributes->>rating равно SQL NULL, в порядке id.','SELECT id,name FROM products WHERE attributes->>\'rating\' IS NULL ORDER BY id;')
add(48,'Remove Tech color attributes','Remove the top-level color key from every Tech product attributes, preserving other keys and other products.','Удаление цвета техники','Удалите ключ color верхнего уровня из attributes всех товаров Tech, сохранив прочие ключи и остальные товары.','UPDATE products SET attributes=attributes-\'color\' WHERE category=\'Tech\';','SELECT id,attributes FROM products ORDER BY id;','modify')
add(48,'Add a JSON promotion flag','Add JSONB promotional:false to every product attributes using concatenation, preserving existing keys.','Флаг акции JSON','Добавьте promotional:false в attributes каждого товара через конкатенацию JSONB, сохранив существующие ключи.','UPDATE products SET attributes=attributes||\'{"promotional":false}\'::jsonb;','SELECT id,attributes FROM products ORDER BY id;','modify')
add(49,'One preference per customer','Create customer_preferences(customer_id integer PRIMARY KEY REFERENCES customers(id),locale text NOT NULL); insert (1,en).','Одна настройка на клиента','Создайте customer_preferences(customer_id integer PRIMARY KEY REFERENCES customers(id),locale text NOT NULL). Вставьте (1,en).','CREATE TABLE customer_preferences(customer_id integer PRIMARY KEY REFERENCES customers(id),locale text NOT NULL); INSERT INTO customer_preferences VALUES(1,\'en\');','SELECT customer_id,locale FROM customer_preferences ORDER BY customer_id;','design')
add(49,'Unique external references','Create external_orders(id integer PRIMARY KEY,external_ref text NOT NULL UNIQUE,order_id integer NOT NULL REFERENCES orders(id)); insert (1,import-101,101).','Уникальные внешние ссылки','Создайте external_orders(id integer PRIMARY KEY,external_ref text NOT NULL UNIQUE,order_id integer NOT NULL REFERENCES orders(id)). Вставьте (1,import-101,101).','CREATE TABLE external_orders(id integer PRIMARY KEY,external_ref text NOT NULL UNIQUE,order_id integer NOT NULL REFERENCES orders(id)); INSERT INTO external_orders VALUES(1,\'import-101\',101);','SELECT id,external_ref,order_id FROM external_orders ORDER BY id;','design')
add(50,'Bounded discount rule','Create promotions(id integer PRIMARY KEY,discount numeric NOT NULL DEFAULT 0 CHECK(discount BETWEEN 0 AND 1)); insert only id=1.','Ограниченный размер скидки','Создайте promotions(id integer PRIMARY KEY,discount numeric NOT NULL DEFAULT 0 CHECK(discount BETWEEN 0 AND 1)). Вставьте только id = 1.','CREATE TABLE promotions(id integer PRIMARY KEY,discount numeric NOT NULL DEFAULT 0 CHECK(discount BETWEEN 0 AND 1)); INSERT INTO promotions(id) VALUES(1);','SELECT id,discount FROM promotions ORDER BY id;','design')
add(50,'Protect a booking duration','Create stays(id integer PRIMARY KEY,start_day date NOT NULL,end_day date NOT NULL,CHECK(end_day>start_day)); insert (1,2024-08-01,2024-08-03).','Положительная длительность проживания','Создайте stays(id integer PRIMARY KEY,start_day date NOT NULL,end_day date NOT NULL,CHECK(end_day>start_day)). Вставьте (1,2024-08-01,2024-08-03).','CREATE TABLE stays(id integer PRIMARY KEY,start_day date NOT NULL,end_day date NOT NULL,CHECK(end_day>start_day)); INSERT INTO stays VALUES(1,\'2024-08-01\',\'2024-08-03\');','SELECT id,start_day,end_day FROM stays ORDER BY id;','design')
add(51,'Sequence with a step','Create batch_number START WITH 10 INCREMENT BY 5. Return three nextval values as first_batch,second_batch,third_batch.','Последовательность с шагом','Создайте batch_number START WITH 10 INCREMENT BY 5. Верните три nextval как first_batch, second_batch и third_batch.','CREATE SEQUENCE batch_number START WITH 10 INCREMENT BY 5; SELECT nextval(\'batch_number\') AS first_batch,nextval(\'batch_number\') AS second_batch,nextval(\'batch_number\') AS third_batch;')
add(51,'Identity range starts at one hundred','Create receipts(id integer GENERATED ALWAYS AS IDENTITY(START WITH 100) PRIMARY KEY,total numeric NOT NULL); insert totals 10 and 20.','Identity с началом 100','Создайте receipts(id integer GENERATED ALWAYS AS IDENTITY(START WITH 100) PRIMARY KEY,total numeric NOT NULL). Вставьте total 10 и 20.','CREATE TABLE receipts(id integer GENERATED ALWAYS AS IDENTITY(START WITH 100) PRIMARY KEY,total numeric NOT NULL); INSERT INTO receipts(total) VALUES(10),(20);','SELECT id,total FROM receipts ORDER BY id;','design')
for exercise in items:
 if exercise['id'] in ['l034-e4','l039-e4','l051-e4']:
  exercise['checkOutput']=True
  exercise['outputOrdered']=exercise['id']=='l039-e4'
 if exercise['id']=='l051-e4':
  exercise['kind']='design'
  exercise['validationSQL']="SELECT start_value,increment_by,last_value FROM pg_sequences WHERE schemaname='public' AND sequencename='batch_number';"
assert len(items)==102
(ROOT/'scripts/extra-foundation-exercises.json').write_text(json.dumps(items,ensure_ascii=False,indent=2)+'\n')
